import boto3
from typing import Dict, Any

def get_s3_client(config: Dict[str, Any]) -> boto3.client:
    return boto3.client("s3", region_name=config.get("region"))

def get_textract_client(config: Dict[str, Any]) -> boto3.client:
    return boto3.client("textract", region_name=config.get("region"))

def get_translate_client(config: Dict[str, Any]) -> boto3.client:
    return boto3.client("translate", region_name=config.get("region"))

def get_comprehend_client(config: Dict[str, Any]) -> boto3.client:
    return boto3.client("comprehend", region_name=config.get("region"))

def get_openai_client(api_key: str):
    from openai import OpenAI
    return OpenAI(api_key=api_key)

import boto3
from storage_client import get_s3_client
from storage_models import PresignedDownloadRequest

def create_presigned_download_url(payload: PresignedDownloadRequest, config: dict = None) -> dict:
    config = config or {}
    s3_client = get_s3_client(config)

    url = s3_client.generate_presigned_url(
        'get_object',
        Params={'Bucket': config["bucket"], 'Key': payload.object_name},
        ExpiresIn=payload.expires_in
    )
    return {"presigned_url": url}

import boto3
from storage_client import get_s3_client
from storage_models import ObjectMetadataRequest

def get_object_metadata(payload: ObjectMetadataRequest, config: dict = None) -> dict:
    config = config or {}
    s3_client = get_s3_client(config)

    response = s3_client.head_object(Bucket=config["bucket"], Key=payload.object_name)
    return {"metadata": response.get("Metadata"), "content_type": response.get("ContentType")}

import boto3
from storage_client import get_s3_client
from storage_models import ListPrefixRequest

def list_objects_with_prefix(payload: ListPrefixRequest, config: dict = None) -> dict:
    config = config or {}
    s3_client = get_s3_client(config)

    bucket_name = payload.bucket or config["bucket"]

    response = s3_client.list_objects_v2(Bucket=bucket_name, Prefix=payload.prefix)

    objects = []
    if "Contents" in response:
        for obj in response["Contents"]:
            objects.append({"object_name": obj["Key"], "size": obj["Size"], "last_modified": obj["LastModified"].isoformat()})

    return {"objects": objects}

import boto3
from storage_client import get_textract_client
from storage_models import StoredDocumentOcrRequest

def run_ocr_on_stored_document(payload: StoredDocumentOcrRequest, config: dict = None) -> dict:
    config = config or {}
    textract_client = get_textract_client(config)

    response = textract_client.start_document_text_detection(
        DocumentLocation={
            'S3Object': {
                'Bucket': config["bucket"],
                'Name': payload.object_name
            }
        }
    )

    return {"job_id": response["JobId"]}
